// Learner data stored in profile.sqlite: runs and their events (05, "Events").
import { z } from "zod";
import { Exercise } from "./exercise/index.ts";
import { Outcome } from "./exercise/outcome.ts";
import { ExerciseKey, ItemKey, LessonKey } from "./keys.ts";
import { EditionId } from "./lang.ts";
import { LocaleExercise } from "./locale.ts";

/** ULID, generated by the client for events (idempotency key) and by the server for runs. */
export const Ulid = z.string().regex(/^[0-9A-HJKMNP-TV-Z]{26}$/);

export const RunKind = z.enum(["lesson", "exam", "review", "practice", "scene", "chat"]);
export const RunStatus = z.enum(["active", "finished", "abandoned"]);

export const LessonResult = z.object({
  /** Mean first-attempt score of scored items, 0..1 (05, "Lifecycle"). */
  score: z.number().min(0).max(1),
  scored: z.number().int().nonnegative(),
  answered: z.number().int().nonnegative(),
});
export type LessonResult = z.infer<typeof LessonResult>;

export const Run = z.object({
  id: Ulid,
  kind: RunKind,
  contextKey: LessonKey.nullable(),
  courseKey: z.string().nullable(),
  edition: EditionId.nullable(),
  status: RunStatus,
  endReason: z.enum(["completed", "timeout", "content_updated", "user"]).nullable(),
  startedAt: z.number().int(),
  finishedAt: z.number().int().nullable(),
  result: LessonResult.nullable(),
});
export type Run = z.infer<typeof Run>;

/** What the learner saw on a page: the exercise with its learner-language texts (05). */
export const PageSnapshot = z.object({ exercise: Exercise, locale: LocaleExercise.nullable() });

export const PageShownPayload = z.object({
  pageIndex: z.number().int().nonnegative(),
  /** Attached by the server. */
  snapshot: PageSnapshot.optional(),
});

/** An answer as the client sends it; an `outcome` sent by the client is dropped. */
export const AnsweredInput = z.object({
  answer: z.unknown(),
  /** 1 for the first attempt; only the first counts for scores (04). */
  attempt: z.number().int().positive(),
  ms: z.number().int().nonnegative(),
});

/** An answer as stored: with the outcome computed by the server. */
export const AnsweredPayload = AnsweredInput.extend({ outcome: Outcome });
export type AnsweredPayload = z.infer<typeof AnsweredPayload>;

/** An event as the client sends it. */
export const EventInput = z.discriminatedUnion("type", [
  z.object({
    id: Ulid,
    type: z.literal("page_shown"),
    itemKey: z.null().optional(),
    payload: PageShownPayload,
  }),
  z.object({ id: Ulid, type: z.literal("answered"), itemKey: ItemKey, payload: AnsweredInput }),
  /** The learner moved on without answering the item (skip, or nothing given at "Check"). */
  z.object({
    id: Ulid,
    type: z.literal("item_skipped"),
    itemKey: ItemKey,
    payload: z.object({}).optional(),
  }),
]);
export type EventInput = z.infer<typeof EventInput>;

/** One message of a tutor chat or a scene (05, "Events"). */
export const LlmTurnPayload = z.object({
  role: z.enum(["user", "assistant"]),
  text: z.string(),
  /** The model that wrote an assistant turn. */
  model: z.string().optional(),
  /** The exercise on screen when the learner wrote. */
  exerciseKey: ExerciseKey.optional(),
  /** Scenes: the partner's line in the learner's language. */
  translation: z.string().optional(),
  /** Scenes: errors in the learner's line. */
  corrections: z
    .array(z.object({ wrong: z.string(), right: z.string(), explanation: z.string() }))
    .optional(),
  /** Scenes: indices of the scene's goals reached so far. */
  goalsMet: z.array(z.number().int().nonnegative()).optional(),
  /** Tutor: the tools the model called for this reply. */
  tools: z.array(z.object({ name: z.string(), args: z.unknown() })).optional(),
});
export type LlmTurnPayload = z.infer<typeof LlmTurnPayload>;

/**
 * A model's verdict on the learner's work (05, "Events"): a writing check or session review in the
 * lesson's `practice` run, or a mistake explanation in the lesson run, on the item it explains.
 */
export const LlmVerdictPayload = z.object({
  task: z.enum(["writing", "review", "explain"]),
  /** The learner's text (writing); empty for a review and an explanation. */
  input: z.string(),
  /** The task's structured output (07); an explanation's text. */
  result: z.unknown(),
  model: z.string(),
  latencyMs: z.number().int().nonnegative(),
  /** Explanation: the attempt at the item it explains (1 = the first answer). */
  attempt: z.number().int().positive().optional(),
  /** Review: the lesson run it reviews (reviews stored before this was kept have none). */
  runId: Ulid.optional(),
});
export type LlmVerdictPayload = z.infer<typeof LlmVerdictPayload>;

export const StoredEvent = z.object({
  id: Ulid,
  runId: Ulid,
  ts: z.number().int(),
  type: z.enum([
    "page_shown",
    "answered",
    "item_skipped",
    "llm_verdict",
    "llm_turn",
    "card_review",
  ]),
  itemKey: z.string().nullable(),
  payload: z.unknown(),
});
export type StoredEvent = z.infer<typeof StoredEvent>;
